expect(console.error).toHaveBeenCalledExactlyOnceWith(
        'Base UI: A `<Toggle>` component rendered in a `<ToggleGroup>` has no explicit `value` prop. This will cause issues between the Toggle Group and Toggle values. Provide the `<Toggle>` with a `value` prop matching the `<ToggleGroup>` values prop type.',
      )

expect(async () => {
          const onValueChange = vi.fn();
          const onOpenChange = vi.fn();
          const { user } = await render(
            <Toolbar.Root>
              <Select.Root
                defaultValue="a"
                onValueChange={onValueChange}
                onOpenChange={onOpenChange}
              >
                <Toolbar.Button disabled render={<Select.Trigger nativeButton={false} />} />
                <Select.Portal>
                  <Select.Positioner>
                    <Select.Popup>
                      <Select.Item value="a" />
                      <Select.Item value="b" />
                    </Select.Popup>
                  </Select.Positioner>
                </Select.Portal>
              </Select.Root>
            </Toolbar.Root>,
          );

          expect(screen.queryByRole('listbox')).toBe(null);

          const trigger = screen.getByRole('combobox');
          expect(trigger).not.toHaveAttribute('disabled');
          expect(trigger).toHaveAttribute('data-disabled');
          expect(trigger).toHaveAttribute('aria-disabled', 'true');

          await user.keyboard('[Tab]');
          expect(trigger).toHaveFocus();

          expect(onOpenChange).toHaveBeenCalledTimes(0);
          expect(onValueChange).toHaveBeenCalledTimes(0);

          await user.keyboard('[ArrowUp]');
          await user.keyboard('[ArrowDown]');
          await user.keyboard('[Enter]');
          await user.keyboard('[Space]');

          expect(onOpenChange).toHaveBeenCalledTimes(0);
          expect(onValueChange).toHaveBeenCalledTimes(0);
        }).toErrorDev([
          'Base UI: A component that acts as a button expected a non-<button> because ' +
            'the `nativeButton` prop is false. Rendering a <button> keeps native behavior while Base UI ' +
            'applies non-native attributes and handlers, which can add unintended extra attributes ' +
            '(such as `role` or `aria-disabled`). Use a non-<button> in the `render` prop, or set ' +
            '`nativeButton` to `true`.',
        ])

expect(render(<Toolbar.Separator />)).rejects.toThrow(
